args:
set -e; podman pull -q --policy=missing docker.io/library/python:3.13-alpine >/dev/null; d=$(podman image inspect --format '{{.Digest}}' docker.io/library/python:3.13-alpine); mkdir -p $ROOT/work; printf 'import socket
for reuse in (0, 1):
    s = socket.socket()
    if reuse:
        s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEPORT, 1)
    try:
        s.bind(("127.0.0.1", 3128)); s.listen(1); print("took-the-port", reuse)
    except OSError:
        print("bind-refused", reuse)
    s.close()
' > $ROOT/work/bind.py; printf '(drgnx-settings :version 1 (drgnx-agents-container-images (("py" . "docker.io/library/python@%s"))))
' "$d" > $CONFIG/settings.el; chmod 600 $CONFIG/settings.el
